'use client';

import React, { useState } from 'react';

export default function RootPage() {
  const [role, setRole] = useState<'farmer' | 'fpo' | 'buyer' | 'admin'>('farmer');
  const [identifier, setIdentifier] = useState('farmer@farm2flow.in');

  const handleDemoSelect = (r: 'farmer' | 'fpo' | 'buyer' | 'admin') => {
    setRole(r);
    setIdentifier(`${r}@farm2flow.in`);
  };

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (role === 'admin') {
      window.location.href = 'http://localhost:3001';
    } else {
      window.location.href = `/pwa?role=${role}`;
    }
  };

  return (
    <div className="min-h-screen bg-[#f8f9ff] text-[#121c2a] flex flex-col justify-center items-center p-4">
      <div className="w-full max-w-[420px] bg-white border border-[#c0c9be] rounded-2xl p-6 shadow-md flex flex-col gap-5">
        
        {/* Brand */}
        <div className="text-center flex flex-col items-center gap-1.5">
          <div className="w-12 h-12 rounded-xl bg-[#14532d] text-[#b1f2be] flex items-center justify-center font-bold">
            <span className="material-symbols-outlined text-[28px]">agriculture</span>
          </div>
          <h1 className="text-[22px] font-extrabold text-[#003b1b]">Farm2Flow</h1>
          <p className="text-[12px] text-[#404941] font-bold">From Farm to Market, Smarter.</p>
        </div>

        {/* 1-Click Role Switcher */}
        <div className="bg-[#eff4ff] p-3 rounded-xl border border-[#c0c9be] flex flex-col gap-2">
          <span className="text-[11px] font-bold text-[#904d00] uppercase">1-Click SIH Demo Role Login</span>
          <div className="grid grid-cols-2 gap-2 text-[12px] font-bold">
            <button type="button" onClick={() => handleDemoSelect('farmer')} className={`p-2 rounded-lg border text-left flex items-center gap-2 ${role === 'farmer' ? 'bg-[#14532d] text-white' : 'bg-white'}`}>
              <span>🌾</span> Farmer
            </button>
            <button type="button" onClick={() => handleDemoSelect('fpo')} className={`p-2 rounded-lg border text-left flex items-center gap-2 ${role === 'fpo' ? 'bg-[#14532d] text-white' : 'bg-white'}`}>
              <span>🏡</span> FPO Hub
            </button>
            <button type="button" onClick={() => handleDemoSelect('buyer')} className={`p-2 rounded-lg border text-left flex items-center gap-2 ${role === 'buyer' ? 'bg-[#14532d] text-white' : 'bg-white'}`}>
              <span>🏪</span> Buyer
            </button>
            <button type="button" onClick={() => handleDemoSelect('admin')} className={`p-2 rounded-lg border text-left flex items-center gap-2 ${role === 'admin' ? 'bg-[#14532d] text-white' : 'bg-white'}`}>
              <span>📊</span> Admin Web
            </button>
          </div>
        </div>

        {/* Login Form */}
        <form onSubmit={handleLogin} className="flex flex-col gap-3">
          <div>
            <label className="text-[12px] font-bold text-[#404941]">Mobile / Email</label>
            <input
              type="text"
              value={identifier}
              onChange={e => setIdentifier(e.target.value)}
              className="w-full px-3.5 py-2.5 mt-1 bg-[#eff4ff] border border-[#c0c9be] rounded-xl text-[14px] font-bold focus:outline-none focus:border-[#003b1b]"
            />
          </div>

          <div>
            <label className="text-[12px] font-bold text-[#404941]">Password</label>
            <input
              type="password"
              defaultValue="demo1234"
              className="w-full px-3.5 py-2.5 mt-1 bg-[#eff4ff] border border-[#c0c9be] rounded-xl text-[14px] font-bold focus:outline-none focus:border-[#003b1b]"
            />
          </div>

          <button
            type="submit"
            className="w-full py-3 bg-[#14532d] text-white rounded-xl text-[15px] font-extrabold hover:bg-[#003b1b] transition-all shadow-md mt-2 flex items-center justify-center gap-2"
          >
            <span>Sign In to {role === 'admin' ? 'Admin Web Command Center' : 'Farm2Flow PWA'}</span>
            <span className="material-symbols-outlined text-[18px]">arrow_forward</span>
          </button>
        </form>
      </div>
    </div>
  );
}
